from collections import Counter
import json,random,time
from pathlib import Path
from direct_attack.native_sparse_policy import profile
from direct_attack.image_policy_broad import seed_inputs,mutate

def metrics(rows,p):
    n=len(rows[0]);G=p['best'];bylabel={}
    for T in G:
        if T.bit_count()<2:continue
        for x,row in enumerate(rows):
            U={row[q] for q in range(n) if T>>q&1}
            if len(U)==1:bylabel.setdefault((x,next(iter(U))),[]).append(T)
    merged={T for Ts in bylabel.values() for T in Ts}
    maximal={T for Ts in bylabel.values() for T in Ts if not any(T!=U and T&U==T for U in Ts)}
    return 1+min(G[T] for T in maximal)-p['best_policy'],sorted(maximal)

root=Path('direct_attack/data/seed_inclusion');root.mkdir(exist_ok=True)
rng=random.Random(20261024);seedrows=seed_inputs(5,3,20261024,True)['rows'];counts=Counter();best=0;started=time.monotonic();found=None
for i in range(200000):
    if i%500==0:current=[list(r) for r in rng.choice(seedrows)];score=0
    rows=mutate(current,rng);counts['tested']+=1;p=profile(rows,True)
    if p is None:continue
    counts['sc_synchronizing']+=1;gap,maximal=metrics(rows,p)
    if gap>best:
        best=gap;found=rows;print(json.dumps(dict(i=i,gap=gap,rows=rows,P=p['best_policy'],maximal=maximal,seconds=time.monotonic()-started)),flush=True)
    if gap>=score or rng.random()<0.02:current=rows;score=gap
report=dict(seed=20261024,n=5,alphabet=3,mutations=200000,counts=dict(counts),best_gap=best,witness_rows=found,seconds=time.monotonic()-started,
            scope='Adaptive sampling only; n<=4 arbitrary-alphabet exclusion is a separate paper argument.')
(root/'n5_search.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8');print(json.dumps(report),flush=True)
